const logger = require('./logger');
const config = require('../config');
const redis = require('redis');
const { promisify } = require('util');

const options = {
    host: config.redis.host,
    port: config.redis.port,
    password: [REDACTED],
};
if (!options.password) {
    delete options.password;
}
const client = redis.createClient(options);

client.on('error', (e) => {
    logger.error('Redis error: ', e);
});

client.on('connect', () => {
    logger.info('Redis connected');
});

const getAsync = promisify(client.get).bind(client);

module.exports = {
    set: (key, value, maxAge = 30 * 24 * 60 * 60) => {
        logger.info('Set redis: ' + key);
        client.setex(key, maxAge, value);
    },
    get: async (key) => await getAsync(key),
    del: (key) => {
        client.del(key);
    },
};

module.exports = {
    port: process.env.PORT || 1207,
    mongodb: {
        username: process.env.MONGO_USERNAME || null,
        password: [REDACTED] || null,
        host: process.env.MONGO_HOST || '127.0.0.1',
        port: process.env.MONGO_PORT || '27017',
        database: process.env.MONGO_DATABASE || 'danmaku',
    },
    redis: {
        host: process.env.REDIS_HOST || '127.0.0.1',
        port: process.env.REDIS_PORT || '6379',
        password: [REDACTED] || null,
    }
};

const Router = require('koa-router');
const router = new Router();

router.get('/v3', require('./routes/get'));
router.post('/v3', require('./routes/post'));
router.get('/v3/bilibili', require('./routes/bilibili'));

module.exports = router;

const Koa = require('koa');
const bodyParser = require('koa-bodyparser');

const logger = require('./utils/logger');
const config = require('./config');

const mongodb = require('./utils/mongodb');
const redis = require('./utils/redis');

const onerror = require('./middleware/onerror');
const header = require('./middleware/header.js');
const accessControl = require('./middleware/access-control.js');

const router = require('./router');

process.on('uncaughtException', (e) => {
    logger.error('uncaughtException: ' + e);
});

logger.info('🎉 DPlayer start! Cheers!');

const app = new Koa();
app.proxy = true;
app.context.mongodb = mongodb;
app.context.redis = redis;

app.use(bodyParser());
app.use(onerror);
app.use(header);
app.use(accessControl);
app.use(router.routes()).use(router.allowedMethods());

app.listen(config.port);
logger.info('Listening Port ' + config.port);

const logger = require('../utils/logger');

module.exports = async (ctx, next) => {
    try {
        await next();
    } catch (err) {
        logger.error('Promise error: ' + (err instanceof Error ? err.stack : err));
        ctx.set({
            'Content-Type': 'text/html; charset=UTF-8',
        });
        ctx.body = `DPlayer-node 发生了一些意外: <pre>${err instanceof Error ? err.stack : err}</pre>`;
        ctx.status = 500;
    }
};

const blacklist = (process.env.BLACKLIST && process.env.BLACKLIST.split(',')) || [];
const whitelist = process.env.WHITELIST && process.env.WHITELIST.split(',');

module.exports = async (ctx, next) => {
    const ip = ctx.ips[0] || ctx.ip;
    const referer = ctx.request.headers.referer;

    const refererAllowed = (whitelist && whitelist.indexOf(referer) !== -1) || blacklist.indexOf(referer) === -1;
    const ipAllowed = (whitelist && whitelist.indexOf(ip) !== -1) || blacklist.indexOf(ip) === -1;

    if (refererAllowed && ipAllowed) {
        await next();
    } else {
        ctx.response.status = 403;

        ctx.body = JSON.stringify({
            code: 1,
            msg: `${!refererAllowed ? '该站点' : '你的 IP '}没有访问权限`,
        });
    }
};

const logger = require('../utils/logger');

module.exports = async (ctx) => {
    const body = ctx.request.body;

    const dan = new ctx.mongodb({
        player: body.id,
        author: body.author,
        time: body.time,
        text: body.text,
        color: body.color,
        type: body.type,
        ip: ctx.ips[0] || ctx.ip,
        referer: ctx.headers.referer,
        date: +new Date(),
    });
    try {
        const data = await dan.save();
        ctx.body = JSON.stringify({
            code: 0,
            data,
        });
        ctx.redis.del(`danmaku${data.player}`);
    }
    catch (err) {
        logger.error(err);
        ctx.body = JSON.stringify({
            code: 1,
            msg: `Database error: ${err}`,
        });
    }
};

const logger = require('../utils/logger');
const headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'Content-Type, Content-Length, Authorization, Accept, X-Requested-With , yourHeaderFeild',
    'Access-Control-Allow-Methods': 'PUT, POST, GET, DELETE, OPTIONS',
    'Content-Type': 'application/json; charset=UTF-8',
    'Cache-Control': 'no-cache',
};

module.exports = async (ctx, next) => {
    logger.info(`${ctx.url}, user IP: ${ctx.ips[0] || ctx.ip}`);
    ctx.set(headers);
    await next();
};

const winston = require('winston');

const logger = winston.createLogger({
    level: 'info',
    format: winston.format.json(),
    transports: [
        //
        // - Write to all logs with level `info` and below to `combined.log`
        // - Write all logs error (and below) to `error.log`.
        //
        new winston.transports.File({
            filename: 'logs/error.log',
            level: 'error',
        }),
        new winston.transports.File({ filename: 'logs/combined.log' }),
    ],
});

//
// If we're not in production then log to the `console` with the format:
// `${info.level}: ${info.message} JSON.stringify({ ...rest }) `
//
logger.add(
    new winston.transports.Console({
        format: winston.format.combine(winston.format.colorize(), winston.format.simple()),
    })
);

module.exports = logger;

const fetch = require('node-fetch');
const cheerio = require('cheerio');

module.exports = async (ctx) => {
    const aid = ctx.request.query.aid;
    let cid = ctx.request.query.cid;

    if (!cid && aid) {
        cid = await ctx.redis.get(`v3bilibiliaid2cid${aid}`);
        if (!cid) {
            const res = await fetch(`http://www.bilibili.com/widget/getPageList?aid=${aid}`);
            const result = await res.json();
            cid = result[0].cid;
            ctx.redis.set(`v3bilibiliaid2cid${aid}`, cid);
        }
    }
    let data = await ctx.redis.get(`v3bilibilicid2dan${cid}`);
    if (data) {
        ctx.response.set('X-Koa-Redis', 'true');
        data = JSON.parse(data);
    } else {
        const res = await fetch(`https://api.bilibili.com/x/v1/dm/list.so?oid=${cid}`);
        const result = await res.text();
        const $ = cheerio.load(result.replace(/[\x00-\x08\x0b-\x0c\x0e-\x1f\x7f]/g, ''), {
            xmlMode: true
        });
        data = $('d').map((i, el) => {
            const item = $(el);
            const p = item.attr('p').split(',');
            let type = 0;
            if (p[1] === '4') {
                type = 2;
            }
            else if (p[1] === '5') {
                type = 1;
            }
            return [[parseFloat(p[0]), type, parseInt(p[3]), p[6], item.text()]];
        }).get();
        ctx.redis.set(`v3bilibilicid2dan${cid}`, JSON.stringify(data), 10 * 60);
        ctx.response.set('X-Koa-Origin', 'true');
    }
    ctx.body = JSON.stringify({
        code: 0,
        data: data,
    });
};

const mongoose = require('mongoose');
const config = require('../config');
const logger = require('./logger');

mongoose.connect(`mongodb://${(config.mongodb.username && config.mongodb.password) ? `${config.mongodb.username}:${config.mongodb.password}@` : ''}${config.mongodb.host}:${config.mongodb.port}/${config.mongodb.database}`);

const db = mongoose.connection;
db.on('error', (e) => {
    logger.error('Mongodb error: ', e);
});
db.once('open', () => {
    logger.info('Mongodb connected');
});

const danmakuSchema = new mongoose.Schema({
    player: {
        type: String,
        index: true,
    },
    author: String,
    time: Number,
    text: String,
    color: Number,
    type: Number,
    ip: String,
    referer: String,
    date: Number,
});
const danmaku = mongoose.model('dan', danmakuSchema);

module.exports = danmaku;

function htmlEncode (str) {
    return str ? str.replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#x27;')
        .replace(/\//g, '&#x2f;') : '';
}

module.exports = async (ctx) => {
    const { id, limit } = ctx.request.query;

    let data = await ctx.redis.get(`danmaku${id}`);
    if (data) {
        data = JSON.parse(data);
        if (limit) {
            data = data.slice(-1 * parseInt(limit));
        }
        ctx.response.set('X-Koa-Redis', 'true');
    } else {
        data = await ctx.mongodb.find({ player: id }) || [];
        ctx.redis.set(`danmaku${id}`, JSON.stringify(data));
        if (limit) {
            data = data.slice(-1 * parseInt(limit));
        }
        ctx.response.set('X-Koa-Mongodb', 'true');
    }
    ctx.body = JSON.stringify({
        code: 0,
        data: data.map((item) => [item.time || 0, item.type || 0, item.color || 16777215, htmlEncode(item.author) || 'DPlayer', htmlEncode(item.text) || '']),
    });
};
